  if (!inspected.valid) {
    return { status: 'unavailable', code: 'invalid-budget', reason: inspected.reason, marginTarget: null, calculation: null };
  }

  const zero: ExactRational = { numerator: '0', denominator: '1' };

  if (input === null || typeof input !== 'object' || input.model === null || typeof input.model !== 'object') {
    return { status: 'unavailable', code: 'invalid-target', reason: 'input inválido', marginTarget: null, calculation: null };
  }

  const { kind, reason: originalReason } = input.model;
  const reason = originalReason.trim();
  if (kind !== 'fixed-usage-linear' || !originalReason || typeof originalReason !== 'string' || !reason) {
